/**
 * Regenerates backend/db/schemaStatements.ts from prisma/schema.prisma.
 *
 *   npm run db:schema-sql
 *
 * The server runs these statements at boot (serverDb.ensureNeonTablesExist) so
 * that a brand-new Neon database gets every table the Prisma client expects —
 * migrations are never run on deploy. Every statement is made idempotent and
 * purely additive: tables and indexes are created only if missing, missing
 * columns are added as nullable, and nothing is ever dropped or altered.
 *
 * Run it after changing schema.prisma and commit the generated file.
 */
const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const sql = execSync('npx prisma migrate diff --from-empty --to-schema-datamodel prisma/schema.prisma --script', {
  cwd: root,
  encoding: 'utf8',
  stdio: ['ignore', 'pipe', 'inherit']
});

const blocks = sql
  .split(/;\s*$/m)
  .map(b => b.split(/\r?\n/).filter(l => !l.trim().startsWith('--')).join('\n').trim())
  .filter(Boolean);

const tables = [];   // { name, create, columns: [sql] }
const indexes = [];  // sql
const foreignKeys = []; // { table, name, sql }

for (const b of blocks) {
  let m;
  if ((m = b.match(/^CREATE TABLE "([^"]+)" \(([\s\S]*)\)$/))) {
    const name = m[1];
    const columns = m[2]
      .split(/,\s*\n/)
      .map(l => l.trim())
      .filter(l => l.startsWith('"'))
      .map(col => {
        // Adding a NOT NULL column without a default fails on a table that has
        // rows, so columns added to an existing table are nullable there.
        const hasDefault = /\bDEFAULT\b/.test(col);
        return hasDefault ? col : col.replace(/\s+NOT NULL\b/, '');
      });
    tables.push({ name, create: b.replace(/^CREATE TABLE /, 'CREATE TABLE IF NOT EXISTS '), columns });
  } else if (/^CREATE (UNIQUE )?INDEX /.test(b)) {
    indexes.push(b.replace(/^CREATE (UNIQUE )?INDEX /, (_, u) => `CREATE ${u || ''}INDEX IF NOT EXISTS `));
  } else if ((m = b.match(/^ALTER TABLE "([^"]+)" ADD CONSTRAINT "([^"]+)" FOREIGN KEY/))) {
    foreignKeys.push({ table: m[1], name: m[2], sql: b });
  } else if (/^CREATE TYPE /.test(b)) {
    // Enums: create only when missing.
    const t = b.match(/^CREATE TYPE "([^"]+)"/)[1];
    tables.unshift({ name: `__type_${t}`, create: `DO $$ BEGIN ${b}; EXCEPTION WHEN duplicate_object THEN NULL; END $$`, columns: [] });
  } else {
    throw new Error('Unrecognised statement from prisma migrate diff:\n' + b);
  }
}

const out = `// GENERATED by scripts/generateSchemaSql.cjs from prisma/schema.prisma — do not edit.
// Regenerate with: npm run db:schema-sql

export interface SchemaTable {
  name: string;
  /** CREATE TABLE IF NOT EXISTS … with the full definition. */
  create: string;
  /** Column definitions, used to add any that an existing table is missing. */
  columns: string[];
}

export const SCHEMA_TABLES: SchemaTable[] = ${JSON.stringify(tables, null, 2)};

export const SCHEMA_INDEXES: string[] = ${JSON.stringify(indexes, null, 2)};

/** Applied only to tables created during the same boot, never to existing data. */
export const SCHEMA_FOREIGN_KEYS: { table: string; name: string; sql: string }[] = ${JSON.stringify(foreignKeys, null, 2)};
`;

const target = path.join(root, 'backend', 'db', 'schemaStatements.ts');
fs.mkdirSync(path.dirname(target), { recursive: true });
fs.writeFileSync(target, out);
console.log(`Wrote ${path.relative(root, target)}: ${tables.length} tables, ${indexes.length} indexes, ${foreignKeys.length} foreign keys.`);
